def search(self, regex: str, flags: int = 0) -> QueryInstance:
    """
    Run a regex test against a dict value (only substring string has to
    match).

    >>> Query().f1.search(r'^\\w+$')

    :param regex: The regular expression to use for matching
    :param flags: regex flags to pass to ``re.search``
    """
    def test(value):
        if not isinstance(value, str):
            return False

        return re.search(regex, value, flags) is not None

    # Include flags in the hash so queries that differ only by flags do not
    # share a Table query-cache entry (see issue #637).
    return self._generate_test(test, ('search', self._path, regex, flags))

def contains_text(self, substring: str) -> QueryInstance:
    """Check if the field contains the given substring (case‑sensitive).

    Non‑string values, missing fields, or ``None`` are treated as non‑matching.

    >>> Query().name.contains_text('son')
    """
    def test(value):
        if not isinstance(value, str):
            return False
        return substring in value

    return self._generate_test(test, ('contains_text', self._path, substring))
